import numpy as np

def feature(current, candidates, tour, start):
    """Forward progress: projection of each unvisited city onto the current direction of travel."""
    if tour.shape[0] < 2:
        return np.zeros(len(candidates))
    h = tour[-1] - tour[-2]
    hn = float(np.hypot(h[0], h[1]))
    if hn < 1e-12:
        return np.zeros(len(candidates))
    u = h / hn
    proj = (candidates - current) @ u          # signed distance ahead along the heading
    return proj / 1.5                          # max possible |proj| ~ sqrt(2)

import numpy as np

def feature(current, candidates, tour, start):
    """Next-step Euclidean distance to each candidate as a fraction of the two-leg path current->candidate->start (near-now but far-from-start scores high)."""
    d = np.linalg.norm(candidates - current, axis=1)
    d_back = np.linalg.norm(candidates - start, axis=1)
    return -(d / (d + d_back + 1e-9))

import numpy as np

def feature(current, candidates, tour, start):
    """Cosine of the turn angle between current heading and each candidate direction; higher = straighter continuation."""
    k = candidates.shape[0]
    if tour.shape[0] < 2:
        return np.zeros(k)
    heading = tour[-1] - tour[-2]
    hnorm = np.linalg.norm(heading)
    if hnorm < 1e-9:
        return np.zeros(k)
    v = candidates - current
    vnorm = np.linalg.norm(v, axis=1)
    return (v @ heading) / (vnorm * hnorm + 1e-9)

import numpy as np

def feature(current, candidates, tour, start):
    """Distance from each candidate to its nearest other unvisited city, divided by its distance to current."""
    k = candidates.shape[0]
    d_cur = np.linalg.norm(candidates - current, axis=1)
    if k > 1:
        diff = candidates[:, None, :] - candidates[None, :, :]
        dm = np.sqrt(np.sum(diff * diff, axis=2))
        np.fill_diagonal(dm, np.inf)
        d_near = dm.min(axis=1)
    else:
        d_near = np.zeros(k)
    return d_near / (d_cur + d_near + 1e-9)

import numpy as np


def feature(current, candidates, tour, start):
    """Soft-min (smooth cap) of the nearest other unvisited city's distance and the candidate's distance to start, minus distance from current."""
    c = candidates
    k = c.shape[0]
    if k == 0:
        return np.zeros(0)
    if k == 1:
        return np.zeros(1)

    d_cur = np.sqrt(np.sum((c - current) ** 2, axis=1))
    dh = np.sqrt(np.sum((c - start) ** 2, axis=1))

    diff = c[:, None, :] - c[None, :, :]
    pair = np.sqrt(np.sum(diff ** 2, axis=2))
    np.fill_diagonal(pair, np.inf)
    nn = np.min(pair, axis=1)

    tau = 0.1
    postpone = -tau * np.log(np.exp(-nn / tau) + np.exp(-dh / tau))

    v = postpone - d_cur
    return v / (np.max(np.abs(v)) + 1e-9)

import numpy as np

def feature(current, candidates, tour, start):
    """Normalized margin between the nearest already-visited city (excluding current) and the current city: (dv - d_cur) / (dv + d_cur)."""
    k = candidates.shape[0]
    if tour.shape[0] < 2:
        return np.zeros(k, dtype=float)

    V = tour[:-1]
    d_cur = np.sqrt(np.sum((candidates - current) ** 2, axis=1))
    dv = np.min(
        np.sqrt(np.sum((candidates[:, None, :] - V[None, :, :]) ** 2, axis=2)),
        axis=1,
    )
    return (dv - d_cur) / (dv + d_cur + 1e-9)

import numpy as np

def feature(current, candidates, tour, start):
    """Nearest-neighbour in-degree of each candidate among the unvisited cities: the share of other unvisited cities for which this candidate is their closest remaining city (hub-ness / normalised)."""
    k = len(candidates)
    if k <= 2:
        return np.zeros(k, dtype=float)
    d = np.linalg.norm(candidates[:, None, :] - candidates[None, :, :], axis=-1)
    np.fill_diagonal(d, np.inf)
    nearest = d.min(axis=1)                       # nearest other-candidate distance for each city j
    # candidate i "wins" j if it is (one of) j's nearest remaining cities
    votes = (d <= (nearest[None, :] + 1e-12)).sum(axis=1)
    val = votes / float(k - 1)
    return np.nan_to_num(np.clip(val, 0.0, 1.0), nan=0.0, posinf=1.0, neginf=0.0)

import numpy as np

def feature(current, candidates, tour, start):
    """Rim isolation: how much farther each candidate sits from its farthest remaining unvisited city than from the current city, as a bounded ratio (edge-of-cloud candidates near the current city score high)."""
    k = len(candidates)
    dcur = np.linalg.norm(candidates - current, axis=1)
    if k <= 1:
        return -dcur / (1.0 + dcur)
    d = np.linalg.norm(candidates[:, None, :] - candidates[None, :, :], axis=-1)
    np.fill_diagonal(d, -1.0)
    far_other = d.max(axis=1)
    return (far_other - dcur) / (far_other + dcur + 1e-9)

import numpy as np

def feature(current, candidates, tour, start):
    """Gate-weighted distance-to-start contrast measured per unit leg: (1-k/n)^2 * (mean(dh)-dh)/(||c-current||+1e-9), clipped to [-gate, gate]."""
    k = candidates.shape[0]
    if k <= 1:
        return np.zeros(k)
    dh = np.linalg.norm(candidates - start, axis=1)
    leg = np.linalg.norm(candidates - current, axis=1)
    n = tour.shape[0] + k
    gate = (1.0 - k / n) ** 2
    vals = gate * (dh.mean() - dh) / (leg + 1e-9)
    out = np.clip(vals, -gate, gate)
    return np.nan_to_num(out, nan=0.0, posinf=0.0, neginf=0.0)
